/*
 * A257706  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 0
 *          and d(1) = 1.
 * https://oeis.org/A257706
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) generated by Rule 1 (OEIS A257706) with a(1)=0, d(1)=1
 * Range:     u8 n <= 185, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

seq_t a(idx_t n)
{
    /* static storage for memoisation */
    static seq_t *a_vals = NULL;      /* a[1..] */
    static size_t a_cap = 0;          /* capacity of a_vals   */
    static bool *a_used = NULL;       /* used values          */
    static size_t a_used_cap = 0;     /* capacity of a_used   */
    static unsigned char *diff_used = NULL; /* used differences  */
    static size_t diff_cap = 0;       /* capacity of diff_used*/
    static int64_t diff_offset = 0;   /* offset for negative diff */
    static idx_t max_n_computed = 0;  /* largest n computed    */
    static bool initialized = false;

    /* initialise once */
    if (!initialized) {
        /* initial capacities */
        a_cap = 16;
        a_vals = (seq_t *)malloc(a_cap * sizeof(seq_t));
        a_used = (bool *)calloc(a_cap, sizeof(bool));

        /* difference array: range [-max_neg, +max_pos] */
        diff_cap = 80001;            /* covers ±40000 */
        diff_offset = diff_cap / 2;  /* offset */
        diff_used = (unsigned char *)calloc(diff_cap, sizeof(unsigned char));

        /* seed values a(1)=0, d(1)=1 */
        a_vals[1] = 0;
        a_used[0] = true;
        diff_used[(size_t)(1 + diff_offset)] = 1;

        max_n_computed = 1;
        initialized = true;
    }

    /* ensure request is within bounds */
    if (n == 0 || n < 1) return 0;

    /* generate terms up to n */
    while (max_n_computed < n) {
        size_t k = max_n_computed;          /* current index */
        seq_t a_k = a_vals[k];

        /* ------- Step 1 : try negative h ------- */
        int64_t a_k_int = (int64_t)a_k;                /* for bounds of h */
        int64_t h_candidate;
        bool found = false;
        int64_t lowest_possible = 1 - a_k_int;         /* 1 - a(k) */
        seq_t next_val = 0;

        for (h_candidate = -1; h_candidate >= lowest_possible; --h_candidate) {
            if (h_candidate == 0) continue;
            size_t idx_diff = (size_t)(h_candidate + diff_offset);
            if (idx_diff >= diff_cap) continue;       /* should not happen */
            if (diff_used[idx_diff]) continue;

            /* compute a(k)+h candidates */
            if (h_candidate >= 0) {
                next_val = a_k + (seq_t)h_candidate;
            } else {
                seq_t sub = (seq_t)(-h_candidate);
                next_val = a_k - sub;
            }

            size_t idx_next = (size_t)next_val;
            if (idx_next >= a_used_cap) {
                size_t new_cap = a_used_cap ? a_used_cap : 16;
                while (idx_next >= new_cap) new_cap <<= 1;
                a_used = (bool *)realloc(a_used, new_cap * sizeof(bool));
                memset(a_used + a_used_cap, 0, (new_cap - a_used_cap) * sizeof(bool));
                a_used_cap = new_cap;
            }
            if (a_used[idx_next]) continue;

            /* found a negative h */
            found = true;
            break;
        }

        /* ------- Step 2 : positive h if no negative found ------- */
        if (!found) {
            seq_t h = 1;
            for (;;) {
                size_t idx_diff = (size_t)(h + diff_offset);
                if (idx_diff >= diff_cap) {
                    /* grow the diff_used array (unlikely) */
                    size_t new_cap = diff_cap;
                    while (idx_diff >= new_cap) new_cap *= 2;
                    diff_used = (unsigned char *)realloc(diff_used, new_cap);
                    memset(diff_used + diff_cap, 0, (new_cap - diff_cap));
                    diff_cap = new_cap;
                }
                if (diff_used[idx_diff]) { ++h; continue; }

                seq_t cand = a_k + h;
                size_t idx_next = (size_t)cand;
                if (idx_next >= a_used_cap) {
                    size_t new_cap = a_used_cap ? a_used_cap : 16;
                    while (idx_next >= new_cap) new_cap <<= 1;
                    a_used = (bool *)realloc(a_used, new_cap * sizeof(bool));
                    memset(a_used + a_used_cap, 0, (new_cap - a_used_cap) * sizeof(bool));
                    a_used_cap = new_cap;
                }
                if (a_used[idx_next]) { ++h; continue; }

                /* accept this positive h */
                next_val = cand;
                h_candidate = (int64_t)h;
                break;
            }
        }

        /* ------- store the term and mark used values ------- */
        size_t next_idx = k + 1;
        if (next_idx >= a_cap) {
            size_t new_cap = a_cap ? a_cap : 16;
            while (next_idx >= new_cap) new_cap <<= 1;
            a_vals = (seq_t *)realloc(a_vals, new_cap * sizeof(seq_t));
            a_cap = new_cap;
        }
        a_vals[next_idx] = next_val;

        /* mark a(next_idx) as used */
        size_t used_a_idx = (size_t)next_val;
        if (used_a_idx >= a_used_cap) {
            size_t new_cap = a_used_cap ? a_used_cap : 16;
            while (used_a_idx >= new_cap) new_cap <<= 1;
            a_used = (bool *)realloc(a_used, new_cap * sizeof(bool));
            memset(a_used + a_used_cap, 0, (new_cap - a_used_cap) * sizeof(bool));
            a_used_cap = new_cap;
        }
        a_used[used_a_idx] = true;

        /* mark the difference as used */
        int64_t diff_idx = h_candidate + diff_offset;
        if (diff_idx >= 0 && (size_t)diff_idx < diff_cap) {
            diff_used[(size_t)diff_idx] = 1;
        } else {
            /* expand if needed (unlikely for n≤10000) */
            size_t new_cap = diff_cap;
            while (diff_idx >= (int64_t)new_cap) new_cap <<= 1;
            diff_used = (unsigned char *)realloc(diff_used, new_cap);
            memset(diff_used + diff_cap, 0, (new_cap - diff_cap));
            diff_cap = new_cap;
            diff_used[(size_t)diff_idx] = 1;
        }

        ++max_n_computed;
    }

    return a_vals[n];
}
